@extends('layouts.app') @section('title',$producto->exists?'Editar producto':'Nuevo producto') @section('content')<div class="heading"><h2>{{ $producto->exists?'Editar producto':'Registrar producto' }}</h2><a class="btn out" href="{{ route('productos.index') }}">Volver</a></div><div class="card"><form method="POST" enctype="multipart/form-data" action="{{ $producto->exists?route('productos.update',$producto):route('productos.store') }}">@csrf @if($producto->exists) @method('PUT') @endif<div class="formgrid"><div class="f"><label>Nombre *</label><input name="nombre" maxlength="50" value="{{ old('nombre',$producto->nombre) }}" required></div><div class="f"><label>Categoría *</label><select name="id_categoria" required><option value="">Seleccionar</option>@foreach($categorias as $cat)<option value="{{ $cat->id_categoria }}" @selected(old('id_categoria',$producto->id_categoria)==$cat->id_categoria)>{{ $cat->nombre }}</option>@endforeach</select></div><div class="f"><label>Precio de venta (Bs) *</label><input name="precio" type="number" min="0.01" step="0.01" value="{{ old('precio',$producto->precio) }}" required></div><div class="f"><label>Estado</label><select name="activo"><option value="1" @selected(old('activo',$producto->activo??true))>Activo</option><option value="0" @selected(!old('activo',$producto->activo??true))>Inactivo</option></select></div><div class="f"><label>Fotografía del producto</label><input name="foto" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">JPG, PNG o WEBP · máximo 2 MB</small>@if($producto->foto)<div style="margin-top:8px"><img src="{{ asset('storage/'.$producto->foto) }}" class="product-img" alt="Fotografía actual"></div>@endif</div><div class="f" style="grid-column:1/-1"><label>Descripción</label><textarea name="descripcion" maxlength="100">{{ old('descripcion',$producto->descripcion) }}</textarea></div></div><button class="btn">Guardar producto</button></form></div>@endsection
